import { lessons, labs, weeks, resources } from './data/curriculum.js';
import { LANGUAGE_KEY, getLanguage, setLanguage, languagePicker, translatePage, tr, matchesLearningSearch } from './i18n.js';
import { createSyncClient, SYNC_STORAGE } from './sync-client.js';
import { createSyncUI } from './sync-ui.js';
import { SYNC_ENDPOINT } from './sync-config.js';
import { securityQuestions } from './data/questions-security.js';
import { performanceQuestions } from './data/questions-performance.js';
import { STORAGE_KEY, DOMAIN_NAMES, DOMAIN_WEIGHTS, localDay, addDays, daysBetween, defaultState, validateState, sameAnswers, selectQuestions, latestAttempts, wrongQuestionIds, domainStats, streak, makeSession, scoreSession, planLength, phaseWindow } from './core.js';

const questions=[...securityQuestions,...performanceQuestions];
const bank=new Map(questions.map(q=>[q.id,q]));
let state=defaultState(), storageError=false;
let cloudClient=null,cloudUI=null,remoteRenderPending=false;
try { const raw=localStorage.getItem(STORAGE_KEY); if(raw)state=validateState(JSON.parse(raw)); } catch {storageError=true;}
if(state.session?.questionIds.some(id=>!bank.has(id)))state.session=null;
let route=location.hash.slice(1)||'dashboard', search='', lessonDomain='all', selectedWeek=0, practiceDomain='all', practiceTopic='all', practiceDifficulty='all', practiceCount=10, reviewing=null;
const app=document.querySelector('#app'), dialog=document.querySelector('#dialog');
const paths={home:'M3 10.5 12 3l9 7.5M5 9v11h5v-6h4v6h5V9',plan:'M8 3v4m8-4v4M4 10h16M5 5h14a1 1 0 0 1 1 1v14H4V6a1 1 0 0 1 1-1Zm3 9h2m4 0h2m-8 3h2',book:'M12 5v16M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Z',quiz:'m9 5 1.5 1.5L13 3M17 5h4M9 12l1.5 1.5L13 10M17 12h4M9 19l1.5 1.5L13 17M17 19h4M3 4v16',lab:'M9 3h6m-5 0v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M8 14h8',review:'M19 5v5h-5M19 10a7 7 0 1 0 0 6M12 8v4l-3 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3l-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-2v-4l2-2-2-4-3-1-1-3Z',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',flame:'M13 2c2 5-3 7 1 10 1-1 2-3 2-4 5 5 5 13-3 14-10 0-10-10-4-14-1 4 1 5 2 5-1-4 4-5 2-11Z',chart:'M4 20V10m8 10V4m8 16v-7',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5.5 5.5 0 0 1 0 11Z',bolt:'m13 2-9 12h7l-1 8 10-13h-7Z',money:'M12 2v20m5-16H9a4 4 0 0 0 0 8h6a4 4 0 0 1 0 8H6',link:'m10 13 4-4M9 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 10a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-2 2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',flag:'M5 22V3m0 1c5-4 9 4 15 0v10c-6 4-10-4-15 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 8v6m0-10v1',play:'m8 4 12 8-12 8Z',folder:'M3 6h7l2 3h9v11H3Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',logout:'M9 4H4v16h5m5-13 5 5-5 5M8 12h12'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(a,b)=>b?Math.round(a/b*100):0;
const doneLessons=()=>lessons.filter(l=>state.lessons[l.id]).length;
const allTasks=()=>weeks.flatMap(w=>w.tasks);
const labDone=l=>l.steps.every((_,i)=>state.labSteps[`${l.id}:step:${i}`])&&l.cleanup.every((_,i)=>state.labSteps[`${l.id}:clean:${i}`]);
const taskDone=t=>state.tasks[t.id]===false?false:!!(state.tasks[t.id]||(t.lessonIds?.length&&t.lessonIds.every(id=>state.lessons[id]))||(t.lessonId&&state.lessons[t.lessonId])||(t.labId&&labs.find(l=>l.id===t.labId)&&labDone(labs.find(l=>l.id===t.labId))));
const doneTasks=()=>allTasks().filter(taskDone).length;
const progress=()=>pct(doneTasks(),allTasks().length);
const hoursDone=()=>Math.round(allTasks().filter(taskDone).reduce((a,t)=>a+t.minutes,0)/60*10)/10;
const currentWeek=()=>Math.min(weeks.length-1,Math.max(0,Math.floor(daysBetween(state.settings.startDate,localDay())*state.settings.hours/70)));
const dateLabel=day=>new Date(day+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric'});
function persistLocalState(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{if(!storageError)toast('浏览器存储不可用，请导出进度备份。');storageError=true;}}
function save(activity=false,{replacement=false}={}){if(activity)state.activity[localDay()]=(state.activity[localDay()]||0)+1;persistLocalState();try{if(replacement)cloudClient?.reset(state);else cloudClient?.changed(state);}catch{toast('同步暂时不可用，本机修改已保留，请稍后重试。');}}
function isEditing(){const focused=document.activeElement;return !!focused?.matches('textarea,input:not([readonly]):not([type=checkbox]):not([type=radio]):not([type=button]):not([type=submit]),select,[contenteditable=true]');}
function requestRemoteRender(){if(isEditing()){remoteRenderPending=true;return;}remoteRenderPending=false;render();}
function initializeCloudSync(){
  const storage={getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value),removeItem:key=>localStorage.removeItem(key)};
  try{cloudClient=createSyncClient({endpoint:SYNC_ENDPOINT,storage,initialState:state,validateRemoteState:incoming=>{if(incoming.session?.questionIds.some(id=>!bank.has(id)))throw new Error('UNSUPPORTED_QUIZ');},onRemote:incoming=>{
    state=validateState(incoming);
    if(reviewing)reviewing=state.history.find(h=>h.id===reviewing.id)||null;
    persistLocalState();requestRemoteRender();
  },onStatus:status=>cloudUI?.update(status)});}catch{
    const status=()=>({phase:'error',error:'UNSUPPORTED_BROWSER',connected:false,configured:!!SYNC_ENDPOINT,lastSync:null,revision:0});
    cloudClient={status,changed:()=>{},reset:()=>{},adoptStorage:()=>{},start:()=>{},syncNow:async()=>{},disconnect:()=>{},getCode:()=>'',connect:async()=>{throw new Error('UNSUPPORTED_BROWSER');}};
  }
  cloudUI=createSyncUI({client:cloudClient,icon,esc,toast,confirm:confirmAction});
}
let toastTimer;function toast(text){const el=document.querySelector('#toast');el.textContent=tr(text);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function navigate(to){if(location.hash==='#'+to){route=to;render();}else location.hash=to;}
function modal(html){dialog.innerHTML=html;translatePage(dialog);dialog.showModal();}
function confirmAction(title,body,label,action){modal(`<form method="dialog"><div class="modal-icon">${icon('info',26)}</div><h2>${esc(title)}</h2>${(Array.isArray(body)?body:[body]).filter(Boolean).map(text=>`<p>${esc(text)}</p>`).join('')}<div class="modal-actions"><button class="btn secondary" value="cancel">取消</button><button class="btn primary" id="confirm-action" value="confirm">${esc(label)}</button></div></form>`);dialog.querySelector('#confirm-action').addEventListener('click',()=>{dialog.close();action();});}
function sourceLinks(sources){return `<div class="sources">${sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${icon('link',14)}${esc(s.title)}${icon('arrow',14)}</a>`).join('')}</div>`;}
function tag(text,color=''){return `<span class="tag ${color}">${esc(text)}</span>`;}
function sectionHeading(kicker,title,sub,action=''){return `<div class="section-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1>${sub?`<p class="subtitle">${esc(sub)}</p>`:''}</div>${action}</div>`;}
const nav=[['dashboard','home','学习总览'],['plan','plan','学习计划'],['learn','book','知识课程'],['practice','quiz','练习与模考'],['labs','lab','实战实验'],['review','review','错题本'],['sync','cloud','云同步']];
function shell(content){const active=route.split('/')[0], week=currentWeek();return `<aside class="sidebar" id="sidebar"><button class="icon-btn sidebar-close" data-action="menu" aria-label="关闭导航">${icon('close',18)}</button><a class="brand" href="#dashboard"><span class="brand-mark"><svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="m20 5 13 7.5v15L20 35 7 27.5v-15Zm0 0v30M7 12.5 20 20l13-7.5" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/></svg></span><span>SAA<span class="brand-light"> Studio</span><small>你的 AWS 架构师学习工作台</small></span></a><div class="workspace-label">LEARNING WORKSPACE</div><nav aria-label="主导航">${nav.map(([key,i,title])=>`<a href="#${key}" class="nav-link ${active===key?'active':''}" ${active===key?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${key==='review'&&wrongQuestionIds(state.attempts).length?`<span class="nav-badge">${wrongQuestionIds(state.attempts).length}</span>`:''}${active===key?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="journey-card"><span class="small-label">每一点进步，都算数</span><div><strong>${progress()}<small>%</small></strong><span>学习计划已完成</span></div><div class="progress-track"><i style="width:${progress()}%"></i></div><p>第 ${week+1} 阶段 / 共 ${weeks.length} 阶段</p></div><a class="nav-link ${active==='resources'?'active':''}" href="#resources">${icon('folder')}<span>资源与考试指南</span>${icon('arrow',16)}</a><a class="nav-link ${active==='settings'?'active':''}" href="#settings">${icon('settings')}<span>计划与数据设置</span></a><div class="profile"><span class="avatar" data-i18n-ignore>${esc(state.settings.name.charAt(0).toUpperCase())}</span><div><strong data-i18n-ignore>${esc(state.settings.name)}</strong><small>未来的 Solutions Architect</small></div><span class="online-dot" title="本地学习空间"></span></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" aria-label="打开导航" aria-expanded="false" aria-controls="sidebar" data-action="menu">${icon('menu')}</button><span>我的学习空间</span>${icon('chevron',13)}<strong>${esc(nav.find(n=>n[0]===active)?.[2]||({resources:'资源与考试指南',settings:'计划与数据设置'}[active])||'学习总览')}</strong></div><div class="topbar-right">${languagePicker()}${cloudUI?.header()||''}<span class="save-indicator"><i></i>${storageError?'存储需要检查':'进度自动保存'}</span><span class="exam-pill">SAA-C03</span></div></header><main id="main" tabindex="-1">${storageError?'<div class="notice warning">浏览器存储不可用或上次数据无法读取。请在设置中导出备份，并检查浏览器存储权限。</div>':''}${content}</main><footer><span>SAA Studio <span class="footer-dot">·</span> 学一点，做一点，再前进一步。</span><span>独立学习项目 · 非 AWS 官方产品</span></footer></div>`;}

function dashboard(){const week=weeks[currentWeek()], latest=Object.values(latestAttempts(state.attempts)), accuracy=pct(latest.filter(a=>a.correct).length,latest.length), next=week.tasks.find(t=>!taskDone(t))||allTasks().find(t=>!taskDone(t));const end=addDays(state.settings.startDate,planLength(state.settings.hours)*7-1);const stats=domainStats(state.attempts);return `${sectionHeading('YOUR NEXT CHAPTER',`准备好更进一步了吗，${state.settings.name}？`,'把大目标拆成小行动。今天也离 AWS 架构师更近一点。',`<div class="date-chip">${icon('plan',17)}${dateLabel(localDay())}<span>${['周日','周一','周二','周三','周四','周五','周六'][new Date().getDay()]}</span></div>`)}<div class="hero"><div class="hero-content"><span class="hero-label"><i></i>${planLength(state.settings.hours)} 周备考计划 · 每周 ${state.settings.hours} 小时</span><h2>从理解架构，<br>到自信做出选择<span>。</span></h2><p>不止记住服务名称，更要知道什么时候选择它。<br>沿着你的专属路线，学知识、做实验、练判断。</p><div class="hero-actions"><button class="btn primary" data-action="continue">继续学习${icon('arrow',18)}</button><a href="#plan" class="hero-link">查看学习计划${icon('chevron',15)}</a></div><span class="hero-meta">${icon('target',15)}建议目标窗口 ${dateLabel(end)} · 达标后再预约考试</span></div><div class="architecture" aria-label="云架构示意图"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><svg class="arch-lines" viewBox="0 0 380 280" fill="none" aria-hidden="true"><path d="M190 75v45M190 120H75v75m115-75h115v75M75 195h230M190 120v95" stroke="#c6cfda" stroke-width="1.5" stroke-dasharray="5 5"/><circle cx="190" cy="120" r="4" fill="#fd8b4a"/></svg><div class="arch-node node-cloud">${icon('cloud',38)}<span>AWS CLOUD</span></div><div class="arch-node node-security">${icon('shield',23)}<span>安全</span></div><div class="arch-node node-resilient">${icon('chart',23)}<span>弹性</span></div><div class="arch-node node-performance">${icon('bolt',23)}<span>高性能</span></div><div class="floating-note">${icon('check',14)}Build. Learn. Grow.</div><span class="arch-caption">THINK LIKE AN ARCHITECT</span></div></div><div class="stats-grid"><div class="stat-card"><span class="stat-icon orange">${icon('book')}</span><div><span>学习进度</span><strong>${progress()}<small>%</small></strong><p>${doneTasks()} / ${allTasks().length} 项任务已完成</p></div><div class="mini-ring" style="--p:${progress()}%"></div></div><div class="stat-card"><span class="stat-icon blue">${icon('quiz')}</span><div><span>练习正确率</span><strong>${latest.length?accuracy:'—'}<small>${latest.length?'%':''}</small></strong><p>${latest.length} 道题的最近一次作答</p></div></div><div class="stat-card"><span class="stat-icon purple">${icon('lab')}</span><div><span>实战实验</span><strong>${labs.filter(labDone).length}<small> / ${labs.length}</small></strong><p>每次实践，都让理解更扎实</p></div></div><div class="stat-card"><span class="stat-icon green">${icon('flame')}</span><div><span>连续学习</span><strong>${streak(state.activity)}<small> 天</small></strong><p>今天的小行动，也是大进步</p></div></div></div><div class="dashboard-columns"><div><section class="panel task-panel"><div class="panel-heading"><div><h2>本阶段的学习清单 <span class="subtle-count">${week.tasks.filter(taskDone).length}/${week.tasks.length}</span></h2><p>第 ${week.id} 阶段 · ${esc(week.title)}</p></div><a class="text-link" href="#plan">完整计划${icon('arrow',15)}</a></div><div class="task-list">${week.tasks.slice(0,4).map(taskRow).join('')}</div>${next?`<div class="panel-foot">${icon('spark',16)}不必一次完成所有事情。先专注眼前这一步。</div>`:'<div class="panel-foot">本阶段已全部完成，去下一阶段看看。</div>'}</section><section class="panel roadmap-panel"><div class="panel-heading"><div><h2>你的成长路线</h2><p>有节奏地前进，给理解留一点时间</p></div><span class="tag">${hoursDone()} / 80 h</span></div><div class="mini-roadmap">${weeks.map((w,i)=>`<button data-action="show-week" data-index="${i}" class="road-step ${i===currentWeek()?'current':''} ${w.tasks.every(taskDone)?'complete':''}"><span>${w.tasks.every(taskDone)?icon('check',18):String(i+1).padStart(2,'0')}</span><strong>${esc(w.title.split('与')[0].slice(0,8))}</strong><small>阶段 ${i+1}</small></button>`).join('')}</div></section></div><div><section class="panel domains-panel"><div class="panel-heading"><div><h2>四大考试领域</h2><p>从不同维度，建立架构思维</p></div>${icon('target',19)}</div>${[1,2,3,4].map((d,i)=>`<a href="#practice" data-domain="${d}" class="domain-row"><span class="domain-icon ${['orange','blue','purple','green'][i]}">${icon(['shield','cloud','bolt','money'][i],18)}</span><div><div><strong>${DOMAIN_NAMES[d]}</strong><span>考纲 ${DOMAIN_WEIGHTS[d]}%</span></div><div class="progress-track"><i style="width:${stats[d].percent}%;background:var(--domain-${d})"></i></div><small>${stats[d].total?`${stats[d].percent}% 正确 · 已练 ${stats[d].total} 题`:'尚未练习，从 10 道题开始'}</small></div></a>`).join('')}<a class="domain-foot" href="#practice">来一组专项练习${icon('arrow',16)}</a></section><section class="tip-card"><span>${icon('spark',18)} ARCHITECT’S NOTE</span><h3>先找约束，再选服务。</h3><p>读题时圈出可用性、成本、运维和性能要求。最好的架构，是最符合业务需求的那个。</p><a href="#learn">建立你的知识地图${icon('arrow',15)}</a></section></div></div>`;}
const kinds={learn:['book','知识学习','blue'],lab:['lab','动手实验','purple'],practice:['quiz','刷题练习','orange'],review:['review','回顾复盘','green']};
function taskRow(t){const [i,label,color]=kinds[t.kind]||kinds.learn;return `<div class="task-row ${taskDone(t)?'done':''}"><label class="check-wrap"><input type="checkbox" data-task="${esc(t.id)}" ${taskDone(t)?'checked':''} aria-label="完成：${esc(t.title)}"><span>${icon('check',12)}</span></label><span class="task-type-icon ${color}">${icon(i,19)}</span><div class="task-info"><button data-action="task-open" data-id="${esc(t.id)}">${esc(t.title)}</button><span>${label}<i>·</i>${t.minutes} 分钟</span></div><button class="icon-btn task-go" aria-label="打开 ${esc(t.title)}" data-action="task-open" data-id="${esc(t.id)}">${icon('chevron',17)}</button></div>`;}
function plan(){const w=weeks[selectedWeek]||weeks[0], window=phaseWindow(selectedWeek,state.settings.hours);return `${sectionHeading('A PLAN YOU CAN FINISH','你的目标，拆成每一步。',`已有 AWS 经验 · 共 80 小时 · 按每周 ${state.settings.hours} 小时安排约 ${planLength(state.settings.hours)} 周`, '<a href="#settings" class="btn secondary">'+icon('settings',17)+'调整计划</a>')}<div class="plan-summary"><div><span class="label">开始日期</span><strong>${dateLabel(state.settings.startDate)}</strong></div><div><span class="label">建议目标窗口</span><strong>${dateLabel(addDays(state.settings.startDate,planLength(state.settings.hours)*7-1))}</strong></div><div><span class="label">已完成任务时长</span><strong>${hoursDone()} <small>/ 80 小时</small></strong></div><div class="plan-overall"><span class="label">总体进度 <b>${progress()}%</b></span><div class="progress-track"><i style="width:${progress()}%"></i></div></div></div><div class="notice">${icon('info',19)}<div><strong>每周 10 小时，留出可持续的节奏。</strong> 建议工作日 4 次 × 90 分钟，周末 1 次 × 4 小时；另留两天休息或补进度。完成清单用于自我确认，不等于实际计时。调整周投入后，80 小时内容不变，阶段日期会自动延展。</div></div><div class="plan-layout"><div class="week-list">${weeks.map((wk,i)=>`<button class="week-tab ${selectedWeek===i?'selected':''}" data-action="select-week" data-index="${i}"><span class="week-number">${wk.tasks.every(taskDone)?icon('check',20):String(i+1).padStart(2,'0')}</span><div><small>阶段 ${i+1} · 10 小时</small><strong>${esc(wk.title)}</strong><div class="progress-track"><i style="width:${pct(wk.tasks.filter(taskDone).length,wk.tasks.length)}%"></i></div></div>${icon('chevron',16)}</button>`).join('')}</div><section class="panel week-detail"><div class="week-detail-head"><span class="eyebrow">PHASE ${String(w.id).padStart(2,'0')}</span><h2>${esc(w.title)}</h2><p>${esc(w.focus)}</p><div class="inline-meta"><span>${icon('plan',15)}${dateLabel(addDays(state.settings.startDate,window.start))} — ${dateLabel(addDays(state.settings.startDate,window.end))}</span><span>${icon('clock',15)}10 小时</span><span>${w.tasks.filter(taskDone).length} / ${w.tasks.length} 完成</span></div></div><div class="week-tasks">${w.tasks.map(t=>`${taskRow(t)}<p class="task-detail">${esc(t.detail)}</p>`).join('')}</div><div class="milestone">${icon('target',24)}<div><strong>本阶段验收</strong><p>${esc(w.milestone)}</p></div></div>${selectedWeek<weeks.length-1?`<button class="btn secondary next-phase" data-action="select-week" data-index="${selectedWeek+1}">下一阶段${icon('arrow',17)}</button>`:''}</section></div>`;}
function learn(){const filtered=lessons.filter(l=>(lessonDomain==='all'||l.domain===Number(lessonDomain))&&matchesLearningSearch(l,search));return `${sectionHeading('BUILD YOUR KNOWLEDGE','看懂服务，更看懂选择。',`${lessons.length} 节核心课程，把零散的服务连成完整的架构思路。`)}<div class="toolbar"><div class="filter-tabs"><button data-action="lesson-filter" data-domain="all" class="${lessonDomain==='all'?'selected':''}">全部课程</button>${[1,2,3,4].map(d=>`<button data-action="lesson-filter" data-domain="${d}" class="${lessonDomain===String(d)?'selected':''}">${DOMAIN_NAMES[d]}</button>`).join('')}</div><label class="search-input">${icon('search',17)}<input id="lesson-search" placeholder="搜索服务或知识点" value="${esc(search)}" aria-label="搜索课程"></label></div><div class="course-grid">${filtered.map(l=>`<a href="#learn/${l.id}" class="course-card"><div class="course-top"><span class="course-symbol d${l.domain}">${icon(['shield','cloud','bolt','money'][l.domain-1],27)}</span><span class="course-number">${l.id.replace('lesson-','').padStart(2,'0')}</span></div><span class="eyebrow">${DOMAIN_NAMES[l.domain]}</span><h2>${esc(l.title)}</h2><p>${esc(l.subtitle)}</p><div class="topic-tags">${l.topics.slice(0,3).map(t=>tag(t)).join('')}</div><div class="course-bottom"><span>${icon('clock',14)}${l.minutes} 分钟</span><strong class="${state.lessons[l.id]?'text-green':''}">${state.lessons[l.id]?'已完成':'开始学习'}${icon(state.lessons[l.id]?'check':'arrow',16)}</strong></div></a>`).join('')||empty('没有找到课程','试试其他服务名称或清除筛选。')}</div>`;}
function lessonDetail(id){const l=lessons.find(l=>l.id===id);if(!l)return empty('课程不存在','请从知识课程列表重新选择。');const next=lessons[lessons.indexOf(l)+1];return `<a href="#learn" class="back-link">← 返回知识课程</a><div class="reading-layout"><article class="panel lesson-article"><span class="eyebrow">${DOMAIN_NAMES[l.domain]} · ${l.minutes} MIN READ</span><h1>${esc(l.title)}</h1><p class="article-lead">${esc(l.subtitle)}</p><div class="topic-tags">${l.topics.map(t=>tag(t)).join('')}</div>${l.sections.map((s,i)=>`<section id="section-${i}"><h2><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</h2>${String(s.body).split('\n').filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('')}<h2>把知识变成架构决策</h2><div class="table-scroll"><table><thead><tr><th>业务约束</th><th>优先考虑</th><th>选择理由</th></tr></thead><tbody>${l.decisions.map(d=>`<tr><td>${esc(d.when)}</td><td><strong>${esc(d.choose)}</strong></td><td>${esc(d.why)}</td></tr>`).join('')}</tbody></table></div><div class="pitfall-box"><h3>${icon('info',18)}容易混淆的地方</h3><ul>${l.pitfalls.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div><h2>学完后，试着回答</h2><ol class="knowledge-checks">${l.checks.map(c=>`<li>${esc(c)}</li>`).join('')}</ol><h2>继续阅读官方资料</h2>${sourceLinks(l.sources)}<div class="article-actions"><button class="btn ${state.lessons[l.id]?'secondary':'primary'}" data-action="complete-lesson" data-id="${l.id}">${icon('check',18)}${state.lessons[l.id]?'已完成 · 点击撤销':'我理解了，标记完成'}</button>${next?`<a href="#learn/${next.id}" class="text-link">下一课${icon('arrow',17)}</a>`:''}</div></article><aside class="reading-aside"><div class="panel"><h3>这一课的学习路径</h3>${l.sections.map((s,i)=>`<button class="toc-link" data-action="scroll-section" data-index="${i}"><span>${i+1}</span>${esc(s.title)}</button>`).join('')}<button class="btn secondary full" data-action="practice-domain" data-domain="${l.domain}">练练这个领域${icon('arrow',16)}</button></div><div class="panel note-panel"><h3>${icon('book',17)}我的学习笔记</h3><p>用自己的话，写下选择依据。</p><textarea data-note="${l.id}" placeholder="在什么场景下，我会选择这个服务？">${esc(state.notes[l.id]||'')}</textarea><small>输入后自动保存，仅保存在此浏览器</small></div></aside></div>`;}
function practice(){if(state.session)return quizView();if(reviewing)return resultView(reviewing);const topics=[...new Set(questions.filter(q=>practiceDomain==='all'||q.domain===Number(practiceDomain)).map(q=>q.topic))].sort();const available=questions.filter(q=>(practiceDomain==='all'||q.domain===Number(practiceDomain))&&(practiceTopic==='all'||q.topic===practiceTopic)&&(practiceDifficulty==='all'||q.difficulty===practiceDifficulty)).length;const exams=state.history.filter(h=>h.mode==='exam');return `${sectionHeading('PRACTICE WITH PURPOSE','每一道题，练的是判断。',`${questions.length} 道原创情景题 · 单选与多选 · 逐项解析 · 官方资料延伸阅读`)}<div class="practice-layout"><section class="panel practice-config"><span class="round-icon orange">${icon('quiz',25)}</span><h2>专项练习</h2><p>针对一个知识领域，一次消化一点。提交后立即查看解析。</p><div class="field"><label for="practice-domain">考试领域</label><select id="practice-domain"><option value="all">全部领域 · 综合练习</option>${[1,2,3,4].map(d=>`<option value="${d}" ${String(d)===practiceDomain?'selected':''}>${DOMAIN_NAMES[d]}（考纲 ${DOMAIN_WEIGHTS[d]}%）</option>`).join('')}</select></div><div class="field"><label for="practice-topic">知识主题</label><select id="practice-topic"><option value="all">全部主题</option>${topics.map(t=>`<option ${t===practiceTopic?'selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select></div><div class="field-pair"><div class="field"><label for="practice-difficulty">难度</label><select id="practice-difficulty">${['all','基础','进阶'].map(d=>`<option value="${d}" ${d===practiceDifficulty?'selected':''}>${d==='all'?'全部难度':d}</option>`).join('')}</select></div><div class="field"><label for="practice-count">每组题量</label><select id="practice-count">${[5,10,20,30].map(n=>`<option value="${n}" ${n===practiceCount?'selected':''}>${n} 道题</option>`).join('')}</select></div></div><button class="btn primary full" data-action="start-practice" ${available?'':'disabled'}>开始练习 · ${Math.min(available,practiceCount)} 题${icon('arrow',18)}</button><small class="config-hint">当前筛选共 ${available} 题 · 每组内不重复</small></section><section class="exam-card"><div class="exam-card-top"><span class="round-icon">${icon('clock',26)}</span><span class="tag">EXAM SIMULATION</span></div><h2>给自己一次<br>完整的考场体验。</h2><p>130 分钟，65 道题。先完成作答，再查看结果。支持标记疑问、题目跳转和自动交卷。</p><div class="exam-metrics"><div><strong>65</strong><span>道情景题</span></div><div><strong>130</strong><span>分钟限时</span></div><div><strong>4</strong><span>考试领域</span></div></div><button class="btn dark full" data-action="start-exam">开始模拟考试${icon('arrow',18)}</button><small>按 20 / 17 / 15 / 13 题覆盖四个领域；多次模拟可能抽到已练题目。</small></section></div><div class="notice">${icon('info',19)}<div>题库为独立编写的学习题，不是真题或考题泄露。模拟正确率仅用于自我评估；AWS 采用 100–1000 的量表计分，720 分通过，不能换算为固定正确率。报名前请结合未见过的官方练习评估。</div></div><section class="panel history-panel"><div class="panel-heading"><div><h2>最近的练习记录</h2><p>${exams.length} 次模考 · ${state.history.length} 次已完成练习</p></div></div>${state.history.length?`<div class="table-scroll"><table><thead><tr><th>练习类型</th><th>完成时间</th><th>题目数</th><th>正确率</th><th></th></tr></thead><tbody>${[...state.history].reverse().slice(0,12).map(h=>`<tr><td>${h.mode==='exam'?'模拟考试':h.mode==='review'?'错题重练':'专项练习'}</td><td>${new Date(h.finishedAt).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</td><td>${h.total}</td><td><strong class="${pct(h.correct,h.total)>=80?'text-green':''}">${pct(h.correct,h.total)}%</strong></td><td><button class="text-link" data-action="review-result" data-id="${esc(h.id)}">查看解析${icon('arrow',15)}</button></td></tr>`).join('')}</tbody></table></div>`:empty('第一组练习，从这里开始','每次完成练习后，正确率与解析会保存在这里。','quiz')}</section>`;}
function quizView(){const s=state.session,q=bank.get(s.questionIds[s.index]),selected=s.answers[q.id]||[],submitted=s.submitted[q.id],isExam=s.mode==='exam';return `<div class="quiz-header"><div><span class="eyebrow">${isExam?'MOCK EXAM':s.mode==='review'?'REVIEW & REMEMBER':'FOCUSED PRACTICE'}</span><h1>${isExam?'SAA-C03 模拟考试':s.mode==='review'?'错题重练':'专项练习'}</h1></div><div>${isExam?`<span class="timer">${icon('clock',19)}<b id="countdown">${timeLeft(s)}</b></span>`:'<span class="tag">练习进度实时保存</span>'}<button class="btn secondary" data-action="pause-quiz">暂时离开</button></div></div><div class="quiz-layout"><section class="panel question-panel"><div class="question-meta"><span>QUESTION ${String(s.index+1).padStart(2,'0')} <small>/ ${s.questionIds.length}</small></span><button class="flag-btn ${s.flagged[q.id]?'flagged':''}" data-action="flag-question">${icon('flag',16)}${s.flagged[q.id]?'已标记':'标记疑问'}</button></div><div class="topic-tags">${tag(DOMAIN_NAMES[q.domain])}${tag(q.topic)}${tag(q.answers.length>1?`多选 · 选择 ${q.answers.length} 项`:'单选')}</div><h2 class="question-stem">${esc(q.stem)}</h2><div class="answer-options" role="group" aria-label="答案选项">${q.options.map((o,i)=>`<label class="answer-option ${selected.includes(i)?'selected':''} ${submitted&&!isExam?(q.answers.includes(i)?'correct':selected.includes(i)?'incorrect':''):''}"><input type="${q.answers.length>1?'checkbox':'radio'}" name="answer" value="${i}" ${selected.includes(i)?'checked':''} ${submitted&&!isExam?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span>${submitted&&!isExam&&q.answers.includes(i)?icon('check',18):''}</label>`).join('')}</div>${submitted&&!isExam?explanation(q,selected):''}<div class="question-actions"><button class="btn secondary" data-action="question-prev" ${s.index===0?'disabled':''}>上一题</button><div>${!isExam&&!submitted?`<button class="btn primary" data-action="submit-answer" ${!selected.length?'disabled':''}>提交答案${icon('check',17)}</button>`:`<button class="btn primary" data-action="question-next">${s.index===s.questionIds.length-1?(isExam?'检查并交卷':'完成练习'):'下一题'}${icon('arrow',17)}</button>`}</div></div></section><aside class="panel question-nav"><h3>答题卡</h3><p>已${isExam?'作答':'提交'} ${s.questionIds.filter(id=>isExam?s.answers[id]?.length:s.submitted[id]).length} / ${s.questionIds.length} 题</p><div class="question-grid">${s.questionIds.map((id,i)=>`<button data-action="goto-question" data-index="${i}" class="${s.index===i?'current':''} ${(isExam?s.answers[id]?.length:s.submitted[id])?'answered':''} ${s.flagged[id]?'has-flag':''}" aria-label="第 ${i+1} 题${s.flagged[id]?'，已标记':''}">${i+1}</button>`).join('')}</div><div class="question-legend"><span><i></i>未答</span><span><i class="answered"></i>已答</span><span><i class="flagged"></i>疑问</span></div><button class="btn secondary full" data-action="finish-quiz">${isExam?'交卷并查看结果':'结束本次练习'}</button><p class="nav-note">${isExam?'离开页面后计时继续。时间到后自动交卷，未答题按错误计入。':'刷新或离开后可以继续；未提交题目不会写入错题本，结束时计为未答。'}</p></aside></div>`;}
function explanation(q,selected){const correct=sameAnswers(selected,q.answers);return `<div class="answer-explanation ${correct?'right':'wrong'}"><h3>${icon(correct?'check':'info',20)}${correct?'回答正确':'再理解一次，就更扎实一点'}<span>正确答案：${q.answers.map(i=>String.fromCharCode(65+i)).join('、')}</span></h3><p>${esc(q.explanation)}</p><details><summary>逐项分析 · 为什么其他选项不合适</summary><div>${q.options.map((o,i)=>`<p><b>${String.fromCharCode(65+i)}${q.answers.includes(i)?' ✓':''}</b> ${esc(q.optionExplanations[i])}</p>`).join('')}</div></details><div class="takeaway">${icon('spark',17)}<span>${esc(q.takeaway)}</span></div><a class="text-link" target="_blank" rel="noopener noreferrer" href="${esc(q.source)}">阅读 AWS 官方资料${icon('link',14)}</a></div>`;}
function timeLeft(s){const secs=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));return `${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;}
function resultView(h){const score=pct(h.correct,h.total);const ids=h.questionIds.filter(id=>bank.has(id));return `${sectionHeading('LEARN FROM EVERY ATTEMPT',score>=80?'这次练习，做得很扎实。':'找到了薄弱点，就有了下一步。','把每次作答变成一次理解，而不只是一个分数。', '<button class="btn secondary" data-action="close-result">返回练习中心</button>')}<div class="result-summary"><div class="result-score" style="--p:${score}%"><div><strong>${score}<small>%</small></strong><span>本次正确率</span></div></div><div><h2>${h.mode==='exam'?'模拟考试':h.mode==='review'?'错题重练':'专项练习'}已完成</h2><p>答对 ${h.correct} / ${h.total} 题 · 用时 ${Math.max(1,Math.round(h.duration/60000))} 分钟</p><p class="muted">这是练习正确率，不是 AWS 官方量表分数。</p><div class="inline-actions"><button class="btn primary" data-action="start-review">复习我的错题${icon('arrow',17)}</button><a class="btn secondary" href="#learn">回到知识课程</a></div></div></div><div class="result-domains">${[1,2,3,4].map(d=>{const qs=ids.filter(id=>bank.get(id).domain===d),right=qs.filter(id=>sameAnswers(h.answers[id]||[],bank.get(id).answers)).length;return `<div class="panel"><span>${DOMAIN_NAMES[d]}</span><strong>${qs.length?pct(right,qs.length)+'%':'—'}</strong><small>${right} / ${qs.length} 题</small></div>`;}).join('')}</div><section class="result-review"><h2>逐题复盘</h2>${ids.map((id,i)=>{const q=bank.get(id),a=h.answers[id]||[],correct=sameAnswers(a,q.answers);return `<details class="panel review-question"><summary><span class="result-badge ${correct?'right':'wrong'}">${correct?'✓':'×'}</span><strong>${i+1}. ${esc(q.stem)}</strong>${tag(q.topic)}</summary><div class="review-question-body"><p class="muted">你的答案：${a.length?a.map(x=>String.fromCharCode(65+x)).join('、'):'未作答'}</p><ol type="A" class="review-options">${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol>${explanation(q,a)}</div></details>`;}).join('')}</section>`;}
function labsPage(){return `${sectionHeading('LEARNING BY BUILDING','做出来，才算真正理解。',`${labs.length} 个实战实验，从架构设计到云上验证。每个步骤都有清晰的验收标准。`)}<div class="notice">${icon('info',20)}<div><strong>开始前先设好预算，结束后记得清理。</strong> 云资源可能产生费用；每个实验都标明成本风险和清理项。网站不会连接你的 AWS 账号或创建资源。资源操作由你在自己的沙盒账号中执行。</div></div><div class="labs-grid">${labs.map((l,i)=>{const complete=l.steps.filter((_,j)=>state.labSteps[`${l.id}:step:${j}`]).length+l.cleanup.filter((_,j)=>state.labSteps[`${l.id}:clean:${j}`]).length,total=l.steps.length+l.cleanup.length;return `<a href="#labs/${l.id}" class="lab-card panel"><div class="lab-card-art art-${i%4}"><span class="lab-art-number">LAB ${String(i+1).padStart(2,'0')}</span><div class="lab-diagram"><i>${icon(['shield','cloud','quiz','chart'][i%4],23)}</i><span></span><i>${icon(['folder','bolt','book','target'][i%4],23)}</i><span></span><i>${icon('check',23)}</i></div><span class="lab-art-caption">${esc(l.services.slice(0,3).join(' / '))}</span></div><div class="lab-card-body"><div class="lab-tags">${tag(l.level)}<span>${icon('clock',14)}${l.minutes} 分钟</span></div><h2>${esc(l.title)}</h2><p>${esc(l.subtitle)}</p><div class="progress-track"><i style="width:${pct(complete,total)}%"></i></div><div class="lab-card-foot"><small>${complete}/${total} 步骤已完成</small><strong>${labDone(l)?'实验已完成':'进入实验'}${icon(labDone(l)?'check':'arrow',16)}</strong></div></div></a>`;}).join('')}</div>`;}
function labDetail(id){const l=labs.find(l=>l.id===id);if(!l)return empty('实验不存在','请从实战实验中重新选择。');const complete=l.steps.filter((_,i)=>state.labSteps[`${id}:step:${i}`]).length+l.cleanup.filter((_,i)=>state.labSteps[`${id}:clean:${i}`]).length,total=l.steps.length+l.cleanup.length;return `<a href="#labs" class="back-link">← 返回实验室</a>${sectionHeading('HANDS-ON LAB',l.title,l.subtitle,tag(labDone(l)?'已完成':'进行中',labDone(l)?'green':''))}<div class="reading-layout"><article class="panel lesson-article lab-article"><div class="topic-tags">${l.services.map(s=>tag(s)).join('')}${tag(l.minutes+' 分钟')}</div><h2>你将完成什么</h2><p>${esc(l.goal)}</p><div class="notice warning"><div><strong>成本与前置准备</strong><p>${esc(l.cost)}</p></div></div><h2>一步一步，搭出你的理解</h2><div class="lab-steps">${l.steps.map((s,i)=>`<section class="lab-step ${state.labSteps[`${id}:step:${i}`]?'completed':''}"><div class="lab-step-title"><label class="check-wrap"><input type="checkbox" data-lab-step="${id}:step:${i}" ${state.labSteps[`${id}:step:${i}`]?'checked':''} aria-label="完成步骤 ${i+1}：${esc(s.title)}"><span>${icon('check',12)}</span></label><h3><small>${String(i+1).padStart(2,'0')}</small>${esc(s.title)}</h3></div><p>${esc(s.detail)}</p><div class="verify"><strong>${icon('target',15)}验收标准</strong><p>${esc(s.verify)}</p></div></section>`).join('')}</div><h2>资源清理，也是实验的一部分</h2><p>逐项验证资源已删除或恢复，再勾选完成。</p><div class="cleanup-list">${l.cleanup.map((c,i)=>`<label><input type="checkbox" data-lab-step="${id}:clean:${i}" ${state.labSteps[`${id}:clean:${i}`]?'checked':''}><span>${esc(c)}</span></label>`).join('')}</div><div class="milestone">${icon('target',25)}<div><strong>你的实验交付物</strong><p>${esc(l.deliverable)}</p></div></div><h2>官方操作参考</h2>${sourceLinks(l.sources)}</article><aside class="reading-aside"><div class="panel lab-progress"><span class="round-icon purple">${icon('lab',25)}</span><h3>${labDone(l)?'实验已完成！':'你的实验进度'}</h3><strong>${pct(complete,total)}<small>%</small></strong><div class="progress-track"><i style="width:${pct(complete,total)}%"></i></div><p>${complete} / ${total} 项完成（含资源清理）</p></div><div class="panel note-panel"><h3>我的实验记录</h3><p>记录架构选择、验证结果与复盘。不要保存密钥或敏感信息。</p><textarea data-note="${id}" placeholder="我的方案 / 遇到的问题 / 验收结果…">${esc(state.notes[id]||'')}</textarea><small>本地自动保存</small></div></aside></div>`;}
function review(){const wrong=wrongQuestionIds(state.attempts),latest=latestAttempts(state.attempts),filtered=questions.filter(q=>wrong.includes(q.id));const stats=domainStats(state.attempts);return `${sectionHeading('TURN MISTAKES INTO PROGRESS','让错过的，成为记住的。','错题依据每道题的最近一次作答更新；重练答对后自动移出。',`<button class="btn primary" data-action="start-review" ${wrong.length?'':'disabled'}>重练错题 · ${Math.min(20,wrong.length)} 题${icon('arrow',17)}</button>`)}<div class="result-domains">${[1,2,3,4].map(d=>`<div class="panel"><span>${DOMAIN_NAMES[d]}</span><strong>${filtered.filter(q=>q.domain===d).length}<small> 道错题</small></strong><small>最近正确率 ${stats[d].total?stats[d].percent+'%':'暂无数据'}</small></div>`).join('')}</div>${filtered.length?`<section class="result-review">${filtered.map(q=>`<details class="panel review-question"><summary><span class="result-badge wrong">${icon('review',17)}</span><strong>${esc(q.stem)}</strong>${tag(q.topic)}</summary><div class="review-question-body"><ol type="A" class="review-options">${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol>${explanation(q,latest[q.id].selected)}<label class="field"><span>复盘笔记</span><textarea data-note="${q.id}" placeholder="这次忽略了什么条件？下次如何判断？">${esc(state.notes[q.id]||'')}</textarea></label></div></details>`).join('')}</section>`:empty('错题本还是空的','完成一组练习后，答错的题会自动收录在这里。已经答对的错题会自动移出。','review','<a class="btn primary" href="#practice">开始一组练习</a>')}`;}
function settings(){return `${sectionHeading('MAKE IT YOURS','按你的节奏，持续前进。','调整时间安排，管理只属于你的学习数据。')}<div class="settings-grid"><section class="panel settings-panel"><h2>我的备考计划</h2><form id="settings-form"><div class="field"><label for="display-name">怎么称呼你</label><input id="display-name" name="name" maxlength="30" required value="${esc(state.settings.name)}"></div><div class="field"><label for="start-date">学习开始日期</label><input id="start-date" name="startDate" type="date" required value="${esc(state.settings.startDate)}"></div><div class="field"><label for="weekly-hours">每周可投入时间</label><select id="weekly-hours" name="hours">${[4,6,8,10,12,15,20].map(n=>`<option value="${n}" ${n===state.settings.hours?'selected':''}>${n} 小时 / 周 · 约 ${planLength(n)} 周完成</option>`).join('')}</select></div><div class="notice compact">80 小时内容分为 8 个阶段。调整投入时间后，自动重算阶段日期；已完成进度会保留。</div><button class="btn primary" type="submit">保存我的计划${icon('check',17)}</button></form></section><div><section class="panel settings-panel"><h2>进度备份与恢复</h2><p>任务、课程、实验、答题记录和笔记会保存在当前浏览器。开启云同步后，加密进度也会同步到连接的设备；清除浏览器数据前请导出备份并保存配对码。</p><a class="text-link settings-sync-link" href="#sync">${icon('cloud',17)}云同步${icon('arrow',15)}</a><div class="inline-actions"><button class="btn secondary" data-action="export">${icon('download',17)}导出进度</button><button class="btn secondary" data-action="import">${icon('upload',17)}导入备份</button><input id="import-file" type="file" accept="application/json,.json" hidden></div><small>导入前会预览备份信息并请求确认；新备份会替换当前进度。</small></section><section class="panel settings-panel readiness"><h2>什么时候适合预约考试？</h2><p>把以下标准当作学习目标，而非通过保证。</p>${readinessItems().map(([yes,text])=>`<div><span class="readiness-check ${yes?'checked':''}">${icon(yes?'check':'target',15)}</span>${text}</div>`).join('')}<a class="text-link" href="https://aws.amazon.com/certification/certified-solutions-architect-associate/" target="_blank" rel="noopener noreferrer">查看官方考试与练习资源${icon('link',14)}</a></section><section class="panel settings-panel danger-zone"><h2>重新开始</h2><p>清空此浏览器中的全部进度、笔记和答题记录。建议先导出备份。</p><button class="btn danger" data-action="reset">清空学习数据</button></section></div></div>`;}
function readinessItems(){const exams=state.history.filter(h=>h.mode==='exam').slice(-2),stats=domainStats(state.attempts);return [[doneTasks()===allTasks().length,'完成全部学习计划，并能解释主要架构取舍'],[labs.every(labDone),'完成全部实验验收与资源清理'],[exams.length===2&&exams.every(h=>pct(h.correct,h.total)>=80),'最近两次完整模拟考试均达到 80%'],[[1,2,3,4].every(d=>stats[d].total>=10&&stats[d].percent>=75),'四个领域各练至少 10 题，最近正确率均达到 75%'],[false,'另外完成未见过的 AWS 官方练习，确认不是记住了题目答案（自行验证）']];}
function resourcesPage(){return `${sectionHeading('GO TO THE SOURCE','可靠的知识，从源头开始。','核心事实依据 AWS 官方考试指南核对于 2026-11-13。预约前请再次检查考试代码及最新要求。')}<div class="exam-facts"><div><span>当前考试</span><strong>SAA-C03</strong></div><div><span>考试题量</span><strong>65 <small>题</small></strong></div><div><span>考试时长</span><strong>130 <small>分钟</small></strong></div><div><span>最低通过量表分</span><strong>720 <small>/ 1000</small></strong></div></div><div class="notice">${icon('info',20)}<div>考试包括 50 道计分题和 15 道不计分题，考场中不会标明；答错或未答均不得分。本站模拟统一计算全部 65 题的正确率，不模拟官方量表换算。已有 AWS 经验是本计划的起点，官方建议约一年相关动手经验。</div></div><div class="resource-grid">${resources.map(r=>`<a class="panel resource-card" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><span class="resource-icon">${icon('book',24)}</span><h2>${esc(r.title)}</h2><p>${esc(r.description||r.detail||'阅读 AWS 官方资料，核对概念并继续深入学习。')}</p><span class="text-link">打开官方资源${icon('arrow',16)}</span></a>`).join('')}</div><section class="panel glossary"><h2>读情景题的四步法</h2><div>${[['01','抓业务目标','先判断要解决的是安全、可用性、性能还是成本问题。'],['02','圈出硬约束','例如低运维、私网访问、毫秒延迟、恢复时间或不能丢数据。'],['03','排除不满足项','架构是否真的满足所有约束？可用性、扩展性和备份不要混为一谈。'],['04','比较取舍','多个方案都能工作时，选择最符合题目成本或运维要求的方案。']].map(([n,t,b])=>`<article><span>${n}</span><h3>${t}</h3><p>${b}</p></article>`).join('')}</div></section>`;}
function empty(title,body,i='search',action=''){return `<div class="empty-state"><span>${icon(i,32)}</span><h3>${esc(title)}</h3><p>${esc(body)}</p>${action}</div>`;}

function render(){remoteRenderPending=false;const focused=document.activeElement;let focusSelector=null;if(focused?.id&&focused.id!=='main')focusSelector='#'+CSS.escape(focused.id);else if(focused?.matches('input[name=answer]'))focusSelector=`input[name=answer][value="${focused.value}"]`;else if(focused?.dataset.task)focusSelector=`[data-task="${CSS.escape(focused.dataset.task)}"]`;else if(focused?.dataset.labStep)focusSelector=`[data-lab-step="${CSS.escape(focused.dataset.labStep)}"]`;else if(focused?.dataset.action)focusSelector=`[data-action="${CSS.escape(focused.dataset.action)}"]${focused.dataset.index?`[data-index="${CSS.escape(focused.dataset.index)}"]`:''}`;const [page,id]=route.split('/');let content;try{content=page==='dashboard'?dashboard():page==='plan'?plan():page==='learn'?(id?lessonDetail(id):learn()):page==='practice'?practice():page==='labs'?(id?labDetail(id):labsPage()):page==='review'?review():page==='settings'?settings():page==='sync'?cloudUI.renderPage():page==='resources'?resourcesPage():dashboard();}catch(e){console.error(e);content=empty('这个页面暂时无法显示','请导出备份后刷新，或从侧边栏重新打开。');}app.innerHTML=shell(content);translatePage(app);translatePage(document.querySelector('.skip-link'));bind();cloudUI?.bind(app);if(focusSelector)app.querySelector(focusSelector)?.focus({preventScroll:true});}
function changeLanguage(next){
  // Keep unsaved settings fields intact when changing the display language.
  const drafts=[...app.querySelectorAll('#settings-form input,#settings-form select,#sync-code-input')].map(el=>({id:el.id,value:el.value}));
  const position=scrollY;
  if(!setLanguage(next))return;
  render();
  for(const draft of drafts){const el=document.getElementById(draft.id);if(el)el.value=draft.value;}
  translatePage(dialog);
  window.scrollTo(0,position);
}
function bind(){app.querySelector('#language-select')?.addEventListener('change',e=>changeLanguage(e.target.value));app.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action,el.dataset)));app.querySelectorAll('[data-task]').forEach(el=>el.addEventListener('change',()=>{const t=allTasks().find(t=>t.id===el.dataset.task);state.tasks[t.id]=el.checked;save(el.checked);render();}));app.querySelectorAll('[data-lab-step]').forEach(el=>el.addEventListener('change',()=>{state.labSteps[el.dataset.labStep]=el.checked;{const labId=el.dataset.labStep.split(':')[0];allTasks().filter(t=>t.labId===labId).forEach(t=>delete state.tasks[t.id]);}save(el.checked);const pos=scrollY;render();window.scrollTo(0,pos);}));app.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>{state.notes[el.dataset.note]=el.value.slice(0,20000);save();}));app.querySelectorAll('a[data-domain]').forEach(el=>el.addEventListener('click',()=>{practiceDomain=el.dataset.domain;practiceTopic='all';}));const searchEl=app.querySelector('#lesson-search');searchEl?.addEventListener('input',()=>{const pos=searchEl.selectionStart;search=searchEl.value;render();const next=app.querySelector('#lesson-search');next.focus();next.setSelectionRange(pos,pos);});for(const [id,fn] of [['practice-domain',v=>{practiceDomain=v;practiceTopic='all';}],['practice-topic',v=>practiceTopic=v],['practice-difficulty',v=>practiceDifficulty=v],['practice-count',v=>practiceCount=Number(v)]])app.querySelector('#'+id)?.addEventListener('change',e=>{fn(e.target.value);render();});app.querySelectorAll('input[name="answer"]').forEach(el=>el.addEventListener('change',()=>{const s=state.session,q=bank.get(s.questionIds[s.index]);s.answers[q.id]=[...app.querySelectorAll('input[name="answer"]:checked')].map(e=>Number(e.value));save();render();}));app.querySelector('#settings-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.settings={name:String(f.get('name')).trim()||'Curtis',startDate:String(f.get('startDate')),hours:Number(f.get('hours'))};save();toast('学习计划已更新，按你的节奏继续。');render();});app.querySelector('#import-file')?.addEventListener('change',importProgress);}
function action(name,d){switch(name){case'menu':{const open=document.querySelector('#sidebar').classList.toggle('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded',String(open));if(open)document.querySelector('.sidebar-close').focus();else document.querySelector('.mobile-menu').focus();break;}case'continue':{const w=weeks[currentWeek()],t=w.tasks.find(t=>!taskDone(t))||allTasks().find(t=>!taskDone(t));if(t)openTask(t);else navigate('practice');break;}case'show-week':selectedWeek=Number(d.index);navigate('plan');break;case'select-week':selectedWeek=Number(d.index);render();break;case'task-open':openTask(allTasks().find(t=>t.id===d.id));break;case'lesson-filter':lessonDomain=d.domain;render();break;case'complete-lesson':{state.lessons[d.id]=!state.lessons[d.id];allTasks().filter(t=>t.lessonId===d.id||t.lessonIds?.includes(d.id)).forEach(t=>delete state.tasks[t.id]);save(state.lessons[d.id]);toast(state.lessons[d.id]?'又掌握了一块知识，继续保持！':'已撤销课程完成状态');render();break;}case'scroll-section':document.querySelector('#section-'+d.index)?.scrollIntoView({behavior:'smooth'});break;case'practice-domain':practiceDomain=d.domain;practiceTopic='all';navigate('practice');break;case'start-practice':startQuiz('practice');break;case'start-exam':confirmAction('开始 130 分钟模拟考试？','65 道题，提交后统一显示答案。离开或刷新后计时仍会继续，未答题按错误计入。','开始考试',()=>startQuiz('exam'));break;case'start-review':if(state.session){toast('请先完成当前练习，再开始错题重练。');navigate('practice');}else startQuiz('review');break;case'pause-quiz':navigate('dashboard');toast(state.session.mode==='exam'?'考试已保存，计时仍在继续。':'练习已保存，可随时继续。');break;case'flag-question':{const s=state.session,id=s.questionIds[s.index];s.flagged[id]=!s.flagged[id];save();render();break;}case'goto-question':state.session.index=Number(d.index);save();render();window.scrollTo(0,0);break;case'question-prev':state.session.index--;save();render();break;case'question-next':if(state.session.index===state.session.questionIds.length-1)requestFinish();else{state.session.index++;save();render();window.scrollTo(0,0);}break;case'submit-answer':submitAnswer();break;case'finish-quiz':requestFinish();break;case'review-result':reviewing=state.history.find(h=>h.id===d.id);render();window.scrollTo(0,0);break;case'close-result':reviewing=null;render();break;case'export':exportProgress();break;case'import':document.querySelector('#import-file').click();break;case'reset':confirmAction('清空全部学习数据？',['这会删除任务、课程、实验进度、笔记与答题记录，无法撤销。请确认已导出需要保留的备份。',cloudClient?.status().connected?'已连接云同步：此操作也会替换云端进度，并传播到其他已连接设备。':''],'确认清空',()=>{state=defaultState();save(false,{replacement:true});reviewing=null;toast('已清空学习数据');render();});break;}}
function openTask(t){if(!t)return;if(t.lessonIds?.length){modal(`<div class="task-modal"><span class="eyebrow">知识学习 · ${t.minutes} MIN</span><h2>${esc(t.title)}</h2><p>${esc(t.detail)}</p><div class="grouped-lessons">${t.lessonIds.map(id=>{const l=lessons.find(l=>l.id===id);return `<a href="#learn/${id}">${icon(state.lessons[id]?'check':'book',17)}${esc(l.title)}${icon('arrow',15)}</a>`;}).join('')}</div><p>完成以上全部课程后，本组任务会自动完成；也可以在计划中手动确认。</p><div class="modal-actions"><button class="btn secondary" id="task-close">关闭</button></div></div>`);dialog.querySelector('#task-close').onclick=()=>dialog.close();dialog.querySelectorAll('a').forEach(a=>a.onclick=()=>dialog.close());return;}if(t.lessonId){navigate('learn/'+t.lessonId);return;}if(t.labId){navigate('labs/'+t.labId);return;}modal(`<div class="task-modal"><span class="eyebrow">${esc(kinds[t.kind]?.[1]||'学习任务')} · ${t.minutes} MIN</span><h2>${esc(t.title)}</h2><p>${esc(t.detail)}</p><div class="modal-actions"><button class="btn secondary" id="task-close">关闭</button><button class="btn primary" id="task-go">${t.kind==='practice'?'去练习':t.kind==='review'?'去复盘':'去学习'}${icon('arrow',16)}</button></div></div>`);dialog.querySelector('#task-close').onclick=()=>dialog.close();dialog.querySelector('#task-go').onclick=()=>{dialog.close();navigate(t.kind==='practice'?'practice':t.kind==='review'?'review':t.kind==='lab'?'labs':'learn');};}
function startQuiz(mode){const qs=selectQuestions(questions,{mode,domain:mode==='review'?'all':practiceDomain,topic:mode==='review'?'all':practiceTopic,difficulty:mode==='review'?'all':practiceDifficulty,count:mode==='review'?20:practiceCount,wrongIds:wrongQuestionIds(state.attempts)});if(!qs.length){toast('当前没有可练习的题目，试试其他筛选。');return;}state.session=makeSession(qs,mode);reviewing=null;save();navigate('practice');window.scrollTo(0,0);}
function recordAttempt(q,selected,mode,sessionId){state.attempts.push({questionId:q.id,selected:[...selected],correct:sameAnswers(selected,q.answers),domain:q.domain,at:new Date().toISOString(),mode,sessionId});state.attempts=state.attempts.slice(-20000);}
function submitAnswer(){const s=state.session,q=bank.get(s.questionIds[s.index]),a=s.answers[q.id]||[];if(s.submitted[q.id])return;if(a.length!==q.answers.length){toast(`这道题需要选择 ${q.answers.length} 个答案。`);return;}s.submitted[q.id]=true;recordAttempt(q,a,s.mode,s.id);save(true);render();}
function requestFinish(){const s=state.session,unanswered=s.questionIds.filter(id=>s.mode==='exam'?!s.answers[id]?.length:!s.submitted[id]).length;confirmAction(s.mode==='exam'?'提交模拟考试？':'结束这次练习？',unanswered?`还有 ${unanswered} 题未${s.mode==='exam'?'作答':'提交'}。结束后这些题计为未答，练习正确率分母包含全部题目。`:'全部题目已完成，提交后查看本次结果与解析。','确认提交',finishQuiz);}
function finishQuiz(){const s=state.session;if(!s)return;const graded={...s,answers:{...s.answers}};if(s.mode!=='exam')for(const id of s.questionIds)if(!s.submitted[id])delete graded.answers[id];if(s.mode==='exam')for(const id of s.questionIds)recordAttempt(bank.get(id),s.answers[id]||[],s.mode,s.id);const score=scoreSession(graded,questions),result={id:s.id,mode:s.mode,questionIds:s.questionIds,answers:graded.answers,correct:score.correct,total:score.total,finishedAt:new Date().toISOString(),duration:Math.min(Date.now()-s.startedAt,s.mode==='exam'?130*60000:Infinity)};state.history.push(result);state.history=state.history.slice(-500);state.session=null;reviewing=result;save(true);if(dialog.open)dialog.close();navigate('practice');window.scrollTo(0,0);}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`saa-studio-progress-${localDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('进度备份已导出');}
async function importProgress(e){const file=e.target.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('备份文件过大（上限 10 MB）');const incoming=validateState(JSON.parse(await file.text()));if(incoming.session?.questionIds.some(id=>!bank.has(id)))throw new Error('备份含当前题库不支持的练习，请先完成该练习再备份。');confirmAction('导入并替换当前进度？',[`备份属于 ${incoming.settings.name}，包含 ${incoming.attempts.length} 次作答、${incoming.history.length} 次完整练习。此操作会替换当前数据，建议先导出当前进度。`,cloudClient?.status().connected?'已连接云同步：此操作也会替换云端进度，并传播到其他已连接设备。':''],'导入备份',()=>{state=incoming;reviewing=null;save(false,{replacement:true});toast('学习进度已恢复');render();});}catch(err){toast(err instanceof SyntaxError?'备份 JSON 格式无效':err.message||'无法读取此备份');}e.target.value='';}
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();const main=document.querySelector('#main');main.focus();main.scrollIntoView({behavior:'smooth'});});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'dashboard';render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{
  if(e.key===LANGUAGE_KEY){if(setLanguage(e.newValue||'zh',{persist:false})){render();translatePage(dialog);}return;}
  if(e.key===SYNC_STORAGE){cloudClient?.adoptStorage(e.newValue);return;}
  // Connected tabs exchange the complete sync envelope, including clocks. A
  // plain state event must not overwrite that metadata or undo a remote reset.
  if(e.key===STORAGE_KEY&&e.newValue&&!cloudClient?.status().connected){try{state=validateState(JSON.parse(e.newValue));cloudClient?.changed(state);requestRemoteRender();}catch{toast('其他窗口的进度无法读取，请刷新检查。');}}
});
document.addEventListener('focusout',()=>setTimeout(()=>{if(remoteRenderPending&&!isEditing())requestRemoteRender();},0));
const syncVisible=()=>{if(document.visibilityState==='visible'&&cloudClient?.status().connected)void cloudClient.syncNow();};
window.addEventListener('focus',syncVisible);window.addEventListener('online',syncVisible);
document.addEventListener('visibilitychange',syncVisible);
setInterval(syncVisible,30000);
setInterval(()=>{const s=state.session;if(s?.mode==='exam'){if(Date.now()>=s.deadline){finishQuiz();toast('考试时间结束，已自动交卷。');}else{const timer=document.querySelector('#countdown');if(timer)timer.textContent=timeLeft(s);}}},1000);
initializeCloudSync();
render();
cloudClient.start();
